 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]

    # Monotone-chain convex hull of the non-background pixels.
    pts = sorted(set((c, r) for r, c in pts))
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    if len(pts) == 1:
        hull = pts
    else:
        lo = []
        for p in pts:
            while len(lo) >= 2 and cross(lo[-2], lo[-1], p) <= 0:
                lo.pop()
            lo.append(p)
        hi = []
        for p in reversed(pts):
            while len(hi) >= 2 and cross(hi[-2], hi[-1], p) <= 0:
                hi.pop()
            hi.append(p)
        hull = lo[:-1] + hi[:-1]

    def inside(x, y):
        if len(hull) == 1:
            return (x, y) == hull[0]
        if len(hull) == 2:
            a, b = hull
            return cross(a, b, (x, y)) == 0 and min(a[0],b[0]) <= x <= max(a[0],b[0]) and min(a[1],b[1]) <= y <= max(a[1],b[1])
        sign = None
        for i, a in enumerate(hull):
            z = cross(a, hull[(i+1) % len(hull)], (x, y))
            if z:
                s = z > 0
                if sign is None: sign = s
                elif sign != s: return False
        return True

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and inside(c, r):
                out[r][c] = 3
    return out
